import java.util.Scanner;

public class Main {
    static long[] puteri = new long[20];

    public static long solve(long number, int pos) {
        long contor = number / puteri[pos];

        if (number % puteri[pos] == 0)
            return pos * contor;

        long a = pos * contor + solve(number % puteri[pos], pos - 1);
        long b = pos * (contor + 1) + solve(puteri[pos] - (number % puteri[pos]), pos - 1);

        return Math.min(a, b);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        puteri[1] = 1;

        for (int i = 2; i <= 17; ++i) {
            puteri[i] = puteri[i - 1] * 10 + 1;
        }

        long n = scanner.nextLong();
        System.out.println(solve(n, 17));
        scanner.close();
    }
}
